4	 *
5	 * Input: the draft .md (the design-doc skill's contract). Output, into --outdir:
6	 *   <slug>.docx  — the document
7	 *   <slug>.xlsx  — one sheet per CSV the draft references (tables/<name>.csv or <name>.csv)
8	 *   <slug>.pdf   — the docx converted with LibreOffice
9	 *   --pptx adds <slug>.pptx (python-pptx); xlsx/pptx do not convert to PDF.
10	 *
11	 * Dependencies are installed on demand into a cache directory and never into
12	 * environment.setup_commands: python3 venv with openpyxl/python-docx (+python-pptx
13	 * for --pptx), LibreOffice from the release tarball via dpkg-deb -x (no root), and
14	 * best-effort CJK fonts. A failed install is not a failed run: the script still
15	 * exits 0 with the summary of what it produced, because the draft is the deliverable
16	 * and this script only makes the showing layers. Exit 1 only when nothing could be
17	 * produced at all (bad arguments, unreadable draft).
18	 *
19	 * Output ends with one JSON line: {"draft", "outdir", "artifacts": [...],
20	 * "deps": [{"name", "state": "cached"|"installed"|"failed"|"skipped", "seconds"}]}.
21	 */
22	import { spawnSync } from "node:child_process";
23	import {
24	  copyFileSync,
25	  existsSync,
26	  mkdirSync,
27	  mkdtempSync,
28	  readFileSync,
