37	// ---------------------------------------------------------------- arguments
38	
39	const argv = process.argv.slice(2);
40	function argOf(flag) {
41	  const i = argv.indexOf(flag);
42	  return i >= 0 ? argv[i + 1] : undefined;
43	}
44	const draftArg = argv.find((a, i) => !a.startsWith("--") && (i === 0 || !["--outdir", "--formats"].includes(argv[i - 1])));
45	const outdir = resolve(argOf("--outdir") ?? "docgen-out");
46	const wantPptx = argv.includes("--pptx");
47	const formats = (argOf("--formats") ?? "docx,xlsx,pdf").split(",").map((s) => s.trim()).filter(Boolean);
48	
49	function fail(message) {
50	  console.error(`generate: ${message}`);
51	  process.exit(1);
52	}
53	if (!draftArg || !existsSync(draftArg)) fail("usage: generate.mjs <draft.md> [--outdir DIR] [--formats docx,xlsx,pdf] [--pptx]");
54	const draft = resolve(draftArg);
55	if (!statSync(draft).isFile()) fail(`${draft} is not a file`);
56	mkdirSync(outdir, { recursive: true });
57	
58	const slug = basename(draft).replace(/\.md$/i, "");
59	const deps = [];
60	function record(name, state, seconds) {
61	  deps.push({ name, state, seconds: Math.round(seconds * 10) / 10 });
62	  console.error(`generate: ${name}: ${state} (${Math.round(seconds * 10) / 10}s)`);
63	}
