67	/** A directory that survives a run, so "first run installs, later runs skip" holds across runs too. */
68	const CACHE = process.env.XDG_CACHE_HOME ?? join(process.env.HOME ?? tmpdir(), ".cache");
69	const DOCGEN_CACHE = join(CACHE, "atomaton-docgen");
70	mkdirSync(DOCGEN_CACHE, { recursive: true });
