76	/** python3 with a venv module, or the record of its absence. */
77	function pythonBin() {
78	  for (const bin of ["python3", "python"]) {
79	    const p = spawnSync(bin, ["-c", "import venv"], { encoding: "utf8" });
80	    if (p.status === 0) return bin;
81	  }
82	  return undefined;
83	}
