85	const needPy = formats.includes("docx") || formats.includes("xlsx") || wantPptx;
86	let venvPython;
87	if (needPy) {
88	  const t0 = Date.now();
89	  const py = pythonBin();
90	  if (!py) {
91	    record("python3-venv", "failed", secondsSince(t0));
92	  } else {
93	    venvPython = join(DOCGEN_CACHE, "venv", "bin", "python");
94	    if (existsSync(venvPython)) {
95	      record("python-docgen-venv", "cached", secondsSince(t0));
96	    } else {
97	      const made = spawnSync(py, ["-m", "venv", join(DOCGEN_CACHE, "venv")], { encoding: "utf8" });
98	      if (made.status !== 0) {
99	        record("python-docgen-venv", "failed", secondsSince(t0));
100	        venvPython = undefined;
101	      } else {
102	        record("python-docgen-venv", "installed", secondsSince(t0));
103	      }
104	    }
105	  }
106	  if (venvPython) {
107	    // The distribution name pip installs is not the name the module imports under, and
108	    // for these three the two never agree: `python-docx` imports as `docx` and
109	    // `python-pptx` as `pptx`. Deriving the import from the pip name by replacing `-`
110	    // with `_` therefore probes `python_docx`, which is not importable even when the
111	    // package is installed -- so the probe failed every run and the package was
112	    // reinstalled every run. Measured: the second run reported `python-docx: installed
113	    // (0.2s)` where the whole point of the install step is that it says `cached`.
114	    const packages = [
115	      { pip: "openpyxl", module: "openpyxl" },
116	      { pip: "python-docx", module: "docx" },
117	      ...(wantPptx ? [{ pip: "python-pptx", module: "pptx" }] : []),
118	    ];
119	    for (const { pip: pkg, module } of packages) {
120	      const t1 = Date.now();
121	      const probe = spawnSync(venvPython, ["-c", `import ${module}`], { encoding: "utf8" });
122	      if (probe.status === 0) {
123	        record(pkg, "cached", secondsSince(t1));
124	        continue;
125	      }
126	      const installed = spawnSync(join(DOCGEN_CACHE, "venv", "bin", "pip"), ["install", "--quiet", pkg], {
127	        encoding: "utf8",
128	      });
129	      record(pkg, installed.status === 0 ? "installed" : "failed", secondsSince(t1));
130	    }
131	  }
132	}
