158	      "libreoffice25.8-en-us_*.deb", // UI language
159	      "libobasis25.8-en-us_*.deb", // the en-US langpack; without it startup dies on "The user interface language cannot be determined."
160	      "libobasis25.8-core_*.deb",
161	      "libobasis25.8-writer_*.deb",
162	      "libobasis25.8-graphicfilter_*.deb",
163	      "libobasis25.8-ooofonts_*.deb",
164	      "libobasis25.8-images_*.deb",
165	    ];
166	    for (const pattern of wanted) {
167	      spawnSync("tar", ["-xzf", tgz, "-C", extractDir, "--wildcards", `LibreOffice_*/DEBS/${pattern}`]);
168	    }
169	    for (const deb of readdirSync(join(extractDir, readdirSync(extractDir)[0], "DEBS"))) {
170	      spawnSync("dpkg-deb", ["-x", join(extractDir, readdirSync(extractDir)[0], "DEBS", deb), loRoot]);
171	    }
172	  } finally {
173	    rmSync(extractDir, { recursive: true, force: true });
174	  }
