181	/**
182	 * CJK fonts, best effort: without them a Japanese PDF is tofu, which is a quality
183	 * problem, not a delivery problem.
184	 *
185	 * They go into `$DOCGEN_CACHE/.fonts`, which is `~/.fonts` for the conversion below --
186	 * the one place LibreOffice is guaranteed to look. It also reads
187	 * `$XDG_DATA_HOME/fonts`, and that is the path this used to install into; a live run
188	 * sets `XDG_DATA_HOME` to the runner's own cache (`atomaton-runner.yml`), where nothing
189	 * here writes, so the fonts were installed, reported `installed`, and never read.
190	 * Measured on a draft with Japanese text: all 74 CJK characters came out through a
191	 * single glyph code of `BAAAAA+NotoSans-Bold`, a Latin-only face, where the same
192	 * conversion with the fonts on the path LibreOffice reads embeds
193	 * `NotoSansCJKhk-Regular`. Text still extracted correctly -- the glyphs are what broke.
194	 */
195	function cjkFonts() {
196	  if (!formats.includes("pdf")) return;
197	  const fontsDir = join(DOCGEN_CACHE, ".fonts");
198	  if (existsSync(fontsDir)) {
199	    record("fonts-noto-cjk", "cached", 0);
200	    return;
201	  }
202	  if (existsSync("/usr/share/fonts/opentype/noto")) {
203	    record("fonts-noto-cjk", "system", 0);
204	    return;
205	  }
206	  const t0 = Date.now();
207	  const dl = spawnSync("apt-get", ["download", "fonts-noto-cjk"], { cwd: DOCGEN_CACHE, encoding: "utf8" });
208	  const deb = readdirSync(DOCGEN_CACHE).find((f) => f.startsWith("fonts-noto-cjk") && f.endsWith(".deb"));
209	  if (dl.status !== 0 || !deb) {
210	    record("fonts-noto-cjk", "failed", secondsSince(t0));
211	    return;
212	  }
213	  const root = join(DOCGEN_CACHE, "font-root");
214	  spawnSync("dpkg-deb", ["-x", join(DOCGEN_CACHE, deb), root]);
215	  mkdirSync(fontsDir, { recursive: true });
216	  for (const f of readdirSync(join(root, "usr/share/fonts/opentype/noto"))) {
217	    copyFileSync(join(root, "usr/share/fonts/opentype/noto", f), join(fontsDir, f));
218	  }
219	  rmSync(root, { recursive: true, force: true });
220	  record("fonts-noto-cjk", "installed", secondsSince(t0));
221	}
222	cjkFonts();
